-- Remove generic seeded placeholders (ids 191-214) that are not real EquipHK items
-- Keep id 215 (Electric Winch 1000kg - Elephant) as it's a real item
DELETE FROM equipment_items WHERE id IN (
  191, 192, 193, 194, 195, 196, 197, 198, 199, 200,
  201, 203, 204, 205, 206, 207, 208, 209, 210, 211,
  212, 213, 214
);
SELECT COUNT(*) as total_items FROM equipment_items;

